mkuse!{use crate :: fmt :: { self , Debug } ;}
mkuse!{use crate :: mem :: ManuallyDrop ;}
mkuse!{use crate :: ops :: { Deref , DerefMut } ;}
mkitem!{mkstruct!{# [doc = " Wrap a value and run a closure when dropped."] # [doc = ""] # [doc = " This is useful for quickly creating destructors inline."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " #![feature(drop_guard)]"] # [doc = ""] # [doc = " use std::mem::DropGuard;"] # [doc = ""] # [doc = " {"] # [doc = "     // Create a new guard around a string that will"] # [doc = "     // print its value when dropped."] # [doc = "     let s = String::from(\"Chashu likes tuna\");"] # [doc = "     let mut s = DropGuard::new(s, |s| println!(\"{s}\"));"] # [doc = ""] # [doc = "     // Modify the string contained in the guard."] # [doc = "     s.push_str(\"!!!\");"] # [doc = ""] # [doc = "     // The guard will be dropped here, printing:"] # [doc = "     // \"Chashu likes tuna!!!\""] # [doc = " }"] # [doc = " ```"] # [unstable (feature = "drop_guard" , issue = "144426")] # [doc (alias = "ScopeGuard")] # [doc (alias = "defer")] pub struct DropGuard < T , F > where F : FnOnce (T) , { inner : ManuallyDrop < T > , f : ManuallyDrop < F > , }}}
mkitem!{mkimpl!{impl < T , F > DropGuard < T , F > where F : FnOnce (T) , { # [doc = " Create a new instance of `DropGuard`."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " #![feature(drop_guard)]"] # [doc = ""] # [doc = " use std::mem::DropGuard;"] # [doc = ""] # [doc = " let value = String::from(\"Chashu likes tuna\");"] # [doc = " let guard = DropGuard::new(value, |s| println!(\"{s}\"));"] # [doc = " ```"] # [unstable (feature = "drop_guard" , issue = "144426")] # [must_use] pub const fn new (inner : T , f : F) -> Self { Self { inner : ManuallyDrop :: new (inner) , f : ManuallyDrop :: new (f) } } # [doc = " Consumes the `DropGuard`, returning the wrapped value."] # [doc = ""] # [doc = " This will not execute the closure. This is implemented as an associated"] # [doc = " function to prevent any potential conflicts with any other methods called"] # [doc = " `into_inner` from the `Deref` and `DerefMut` impls."] # [doc = ""] # [doc = " It is typically preferred to call this function instead of `mem::forget`"] # [doc = " because it will return the stored value and drop variables captured"] # [doc = " by the closure instead of leaking their owned resources."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " #![feature(drop_guard)]"] # [doc = ""] # [doc = " use std::mem::DropGuard;"] # [doc = ""] # [doc = " let value = String::from(\"Nori likes chicken\");"] # [doc = " let guard = DropGuard::new(value, |s| println!(\"{s}\"));"] # [doc = " assert_eq!(DropGuard::into_inner(guard), \"Nori likes chicken\");"] # [doc = " ```"] # [unstable (feature = "drop_guard" , issue = "144426")] # [inline] pub fn into_inner (guard : Self) -> T { let mut guard = ManuallyDrop :: new (guard) ; let value = unsafe { ManuallyDrop :: take (& mut guard . inner) } ; unsafe { ManuallyDrop :: drop (& mut guard . f) } ; value } }}}
mkitem!{mkimpl!{# [unstable (feature = "drop_guard" , issue = "144426")] impl < T , F > Deref for DropGuard < T , F > where F : FnOnce (T) , { type Target = T ; fn deref (& self) -> & T { & * self . inner } }}}
mkitem!{mkimpl!{# [unstable (feature = "drop_guard" , issue = "144426")] impl < T , F > DerefMut for DropGuard < T , F > where F : FnOnce (T) , { fn deref_mut (& mut self) -> & mut T { & mut * self . inner } }}}
mkitem!{mkimpl!{# [unstable (feature = "drop_guard" , issue = "144426")] impl < T , F > Drop for DropGuard < T , F > where F : FnOnce (T) , { fn drop (& mut self) { let inner = unsafe { ManuallyDrop :: take (& mut self . inner) } ; let f = unsafe { ManuallyDrop :: take (& mut self . f) } ; f (inner) ; } }}}
mkitem!{mkimpl!{# [unstable (feature = "drop_guard" , issue = "144426")] impl < T , F > Debug for DropGuard < T , F > where T : Debug , F : FnOnce (T) , { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt :: Debug :: fmt (& * * self , f) } }}}